if (n == 0) return 1.;

const double absAlpha = std::abs(alpha);
// For small n, use direct calculation to avoid Stirling overhead
if (n < 20) {
    dcomp alpha_n = 1.;
    for (unsigned long i = 1; i <= n; ++i) {
        alpha_n *= alpha / std::sqrt(double(i));
    }
    return alpha_n * std::exp(-0.5 * absAlpha * absAlpha);
}

// For large n, use Stirling's approximation: n! ≈ sqrt(2πn) * (n/e)^n
// So, alpha^n / sqrt(n!) ≈ alpha^n * exp(0.5 * log(2πn) + n - n*log(n))
const double logNFact = 0.5 * std::log(2 * M_PI * n) + n * (std::log(n) - 1);
const dcomp logAlphaN = n * std::log(alpha);
const dcomp logTerm = logAlphaN - 0.5 * logNFact;
const dcomp result = std::exp(logTerm - 0.5 * absAlpha * absAlpha);

// Handle potential overflow in exp by checking real part
if (std::real(logTerm) > 700) { // exp(700) is near double overflow
    const dcomp scaledLogTerm = logTerm - std::real(logTerm) + 700;
    return std::exp(scaledLogTerm - 0.5 * absAlpha * absAlpha) * 
           std::exp(std::real(logTerm) - 700);
}
return result;

